INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('4279801f-275d-4e0b-8094-35a806b33480','6fbf39ae-6b19-4182-b4c2-6a8d25c86c0f',$$Council Member Hang prioritizes getting unhoused neighbors off the streets and into housing with supportive services, a services-and-housing approach to homelessness.$$,ARRAY['https://www.weho.org/city-government/city-council/councilmembers/danny-hang']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
