INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('4279801f-275d-4e0b-8094-35a806b33480','669cac97-66a6-4087-b036-936fbe62efb3',$$Hang calls housing his top priority, saying West Hollywood faces a serious housing shortage and "needs to do its part by making it easier to build more housing at all income levels" — a strongly pro-supply position.$$,ARRAY['https://beverlypress.com/2026/01/danny-hang-begins-term-as-wehos-vice-mayor/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
