INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('4279801f-275d-4e0b-8094-35a806b33480','e9ebefcd-c496-45e8-b816-a79f8442ba85',$$Hang frames public safety broadly — "keeping people safe in their bodies, their homes, their streets" — emphasizing street lighting, sidewalk safety, healthcare access, and food insecurity over enforcement alone, a holistic, services-oriented approach.$$,ARRAY['https://wehoonline.com/wehos-newest-councilmember-mind/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
